from datetime import datetime, timedelta

# parse simple ICS events
def events(path):
    evs=[]
    lines=open(path).read().splitlines()
    cur={}
    for line in lines:
        if line=='BEGIN:VEVENT': cur={}
        elif line=='END:VEVENT': evs.append(cur)
        elif ':' in line:
            k,v=line.split(':',1)
            cur[k.strip()]=v.strip()
    return evs

def dt(v):
    return datetime.strptime(v, '%Y%m%dT%H%M%SZ')

cal={}
for name in ['alice','bob','carol']:
    cal[name]=[(dt(e['DTSTART']),dt(e['DTEND'])) for e in events(f'/app/{name}_calendar.ics')]

# Hard availability
# Alice: 09:00 - 14:00 (end <= 14:00)
# Bob: start >= 10:00; on Tue/Thu end <= 16:30; else end <= 18:00
# Carol: 09:00 - 17:00 (end <= 17:00); lunch 12:00-12:30 unavailable
start = datetime(2024,1,15,9,0,0)
end = datetime(2024,1,20,0,0,0)
slots=[]
t=start
while t + timedelta(hours=1) <= end and t.hour < 18:
    e=t+timedelta(hours=1)
    if t+timedelta(hours=1) <= datetime(2024,1,20,0,0,0):
        # within business days?
        day=t.date()
        # global business hours 9-18
        if t.hour < 9 or e.hour > 18 or (e.hour==18 and e.minute>0):
            t+=timedelta(minutes=1); continue
        # individual Alice hard: 09:00 <= start and end <= 14:00
        alice_ok = t.hour >= 9 and (e.hour < 14 or (e.hour==14 and e.minute==0))
        # Bob
        bob_ok = t.hour >= 10
        if day.weekday() in (1,3):  # Tue/Thu
            bob_ok = bob_ok and (e.hour < 16 or (e.hour==16 and e.minute<=30))
        else:
            bob_ok = bob_ok and e.hour <= 18
        # Carol available 9-17 and lunch
        carol_ok = t.hour >= 9 and (e.hour < 17 or (e.hour==17 and e.minute==0))
        # lunch overlap: meeting must not overlap 12:00-12:30
        if carol_ok:
            lunch_start = t.replace(hour=12, minute=0)
            lunch_end = t.replace(hour=12, minute=30)
            # check overlap
            if max(t, lunch_start) < min(e, lunch_end):
                carol_ok = False
        # also Carol buffer after late meetings ending >=16:45 (none)
        if all([alice_ok,bob_ok,carol_ok]):
            # check existing events no overlap, and Carol buffer 15 after existing events ending >=16:45
            conflict=False
            for name,evs in cal.items():
                for (s,en) in evs:
                    if s < e and t < en:
                        conflict=True; break
                    # Carol buffer: if existing event ends >=16:45, Carol unavailable until end+15
                    if name=='carol' and en.hour>=16 and (en.hour>16 or en.minute>=45):
                        if e > en and t < en + timedelta(minutes=15) and s < en+timedelta(minutes=15) and t < en+timedelta(minutes=15):
                            conflict=True; break
                if conflict: break
            if not conflict:
                slots.append(t)
    t+=timedelta(minutes=1)

for s in slots:
    print(s.strftime('%a %Y-%m-%d %H:%M'), '-', (s+timedelta(hours=1)).strftime('%H:%M'))
print('count', len(slots))
