    return evs

def dt(v):
    return datetime.strptime(v, '%Y%m%dT%H%M%SZ')

cal={}
for name in ['alice','bob','carol']:
    cal[name]=[(dt(e['DTSTART']),dt(e['DTEND'])) for e in events(f'/app/{name}_calendar.ics')]

start = datetime(2024,1,15,9,0,0)
end = datetime(2024,1,19,18,0,0)
slots=[]
t=start
while t + timedelta(hours=1) <= end:
    e=t+timedelta(hours=1)
    day=t.date()
    # business hours 9-18
    if t.hour < 9 or e.hour > 18:
        t+=timedelta(minutes=1); continue
    # Alice hard: end <= 14:00, start >=9
    alice_ok = t.hour >= 9 and e <= t.replace(hour=14, minute=0)
    # Bob: start >=10; Tue/Thu end<=16:30 else end<=18
    bob_ok = t.hour >= 10
    if day.weekday() in (1,3):
        bob_ok = bob_ok and e <= t.replace(hour=16, minute=30)
    else:
        bob_ok = bob_ok and e <= t.replace(hour=18, minute=0)
    # Carol: start>=9 end<=17, lunch block
    carol_ok = t.hour >= 9 and e <= t.replace(hour=17, minute=0)
    lunch_start = t.replace(hour=12, minute=0)
    lunch_end = t.replace(hour=12, minute=30)
    if max(t, lunch_start) < min(e, lunch_end):
        carol_ok = False
    if not (alice_ok and bob_ok and carol_ok):
        t+=timedelta(minutes=1); continue
    conflict=False
    for name,evs in cal.items():
